## Build URL with Query Parameters

Here's a clean, well-documented JavaScript function that constructs a URL from a base path and query parameters object:

```javascript
/**
 * Builds a URL by combining a base path with query parameters.
 *
 * @param {string} basePath - The base URL or path
 * @param {Object} params - An object containing query parameters
 * @returns {string} The complete URL with query parameters
 * @throws {TypeError} If basePath is not a string or params is not an object
 */
function buildUrl(basePath, params = {}) {
  if (typeof basePath !== "string" || !basePath.trim()) {
    throw new TypeError("basePath must be a non-empty string");
  }

  if (typeof params !== "object" || params === null || Array.isArray(params)) {
    throw new TypeError("params must be a plain object");
  }

  const url = new URL(
    basePath.startsWith("http") ? basePath : `https://${basePath}`
  );

  Object.entries(params).forEach(([key, value]) => {
    if (value === null || value === undefined) return; // Skip null/undefined values

    if (Array.isArray(value)) {
      // Handle array values (e.g., tags=js&tags=css)
      value.forEach((item) => url.searchParams.append(key, item));
    } else {
      url.searchParams.set(key, value);
    }
  });

  return url.toString();
}
```

