/**
 * Builds a URL with a base path and a query parameters object.
 * This version is robust and handles existing query parameters in the base path.
 *
 * @param {string} basePath The base URL or path (e.g., 'https://api.example.com/users').
 * @param {object} params An object of query parameters to add (e.g., { role: 'admin', page: 1 }).
 * @returns {string} The complete URL string.
 */
function buildUrl(basePath, params) {
  // The URL constructor is the best way to parse and manipulate URLs.
  // A dummy base is provided for cases where basePath is just a path like '/users'.
  const url = new URL(basePath, 'http://dummy.base');

  // Iterate over the params object and append each key-value pair.
  // URLSearchParams will automatically handle URL encoding.
  for (const [key, value] of Object.entries(params)) {
    // Skip null or undefined values, as they are often unintentional.
    if (value !== null && value !== undefined) {
      url.searchParams.append(key, value);
    }
  }

  // If the original basePath was relative (e.g., '/users'),
  // return just the path and the search string.
  if (basePath.startsWith('/')) {
    return `${url.pathname}${url.search}`;
  }

  return url.toString();
}

