### 1. Best Practice: Using `URLSearchParams`

This approach is recommended because it's clean, readable, and less error-prone. It correctly handles special characters, arrays, and other edge cases.

```javascript
/**
 * Builds a URL with a base path and a query parameters object.
 *
 * @param {string} baseUrl The base URL or path.
 * @param {object} params An object of key-value pairs for the query parameters.
 * @returns {string} The final, constructed URL.
 */
function buildUrl(baseUrl, params) {
  // Create a URLSearchParams object.
  // This object will handle the encoding and formatting of the query string.
  const searchParams = new URLSearchParams();

  // Return the base URL if no params are provided.
  if (!params) {
    return baseUrl;
  }

  // Iterate over the keys in the params object.
  for (const key in params) {
    const value = params[key];

    // Skip null and undefined values, as they don't make sense in a URL.
    if (value === null || value === undefined) {
      continue;
    }

    // If the value is an array, append each item separately.
    // This creates parameters like `key=value1&key=value2`.
    if (Array.isArray(value)) {
      value.forEach(item => {
        searchParams.append(key, item);
      });
    } else {
      // Otherwise, just append the key-value pair.
      searchParams.append(key, value);
    }
  }

  // Convert the searchParams object to a string (e.g., "key1=value1&key2=value2").
  const queryString = searchParams.toString();

  // If the query string is empty, just return the base URL.
  if (!queryString) {
    return baseUrl;
  }

  // Check if the base URL already has query parameters.
  // If it does, use '&' to append; otherwise, use '?'.
  const separator = baseUrl.includes('?') ? '&' : '?';

  return `${baseUrl}${separator}${queryString}`;
}
```

